// Read-only report on IDENTITY SEQUENCES that have fallen BEHIND their table.
//
// WHAT BREAKS WHEN ONE DOES, in the owner's words: "i cant create project".
//
// Every id column here is `GENERATED BY DEFAULT AS IDENTITY` (verified against
// the live DB 2026-08-24 via information_schema.columns.identity_generation).
// "BY DEFAULT" means Postgres ACCEPTS an explicit id and does NOT advance the
// sequence, silently. So any bulk copy that carries its own ids — the ZANOTTI
// twin duplications, the monthly event CSV imports, a checklist copy — leaves
// the sequence pointing at numbers the table already uses, with no warning and
// no error at the time.
//
// The bill arrives later, on the next ORGANIC insert from the app. New Project
// clones its checklist template into project_checklist_sections and
// project_checklist without supplying ids, so it draws from the poisoned
// sequence, hits duplicate-key on the primary key, and the whole create 500s
// behind a generic "Something went wrong". Twice now — 2026-08-21 and again
// 2026-08-24, three days apart, same two tables.
//
// It also leaves debris: there is no transaction around create, so each failed
// click leaves an EMPTY project row (0 sections, 0 tasks) on the calendar.
// This check counts those too, because they are the visible half of the fault
// and the half the owner reports.
//
// WHY A SCRIPT AND A WORKFLOW: the answer lives only in production, so
// answering it used to mean a person with the production password opening a SQL
// console. Actions already holds secrets.DATABASE_URL for the deploy.
//
// Strictly SELECTs. No DDL, no writes, no transaction. Exits 0 for every
// legitimate answer including "drift found" — the ANSWER is the output, and a
// red job would read as "the check broke". Only an unreachable database or a
// query error exits non-zero. To FIX what this reports, run
// scripts/repair-sequence-drift.mjs (MODE=apply), which is the write half and
// carries its own confirm gate.
import { readFileSync } from "node:fs";
import postgres from "postgres";

// Same resolution order as pg-migrate.mjs: env wins so CI needs no .dev.vars.
function resolveUrl() {
  if (process.env.DATABASE_URL) return process.env.DATABASE_URL;
  try {
    return readFileSync(".dev.vars", "utf8").match(/DATABASE_URL="([^"]+)"/)?.[1];
  } catch {
    return undefined;
  }
}

const url = resolveUrl();
if (!url) {
  console.error("DATABASE_URL not set and no .dev.vars — cannot reach the database.");
  process.exit(1);
}

const sql = postgres(url, { max: 1, idle_timeout: 5, connect_timeout: 15 });

// Table / column names come from pg_catalog, never from a caller, so they are
// already valid identifiers. Quote them anyway: a lowercase-looking name is not
// proof, and `unsafe()` does no quoting of its own.
const q = (id) => `"${String(id).replace(/"/g, '""')}"`;

// A sequence AHEAD of max(id) is correct and normal — gaps are free, and every
// rolled-back insert leaves one. Only BEHIND is a fault, so only `drift > 0` is
// reported. Owning column resolved through pg_depend rather than by guessing
// the `<table>_<col>_seq` name, because project_finance's sequence is attached
// to `project_id`, not to an `id`.
const DRIFT = `
  SELECT c.relname AS seq, dc.relname AS tbl, a.attname AS col
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
    JOIN pg_depend d ON d.objid = c.oid AND d.deptype IN ('a', 'i')
    JOIN pg_class dc ON dc.oid = d.refobjid
    JOIN pg_attribute a ON a.attrelid = dc.oid AND a.attnum = d.refobjsubid
   WHERE c.relkind = 'S'
   ORDER BY dc.relname, a.attname`;

try {
  const owned = await sql.unsafe(DRIFT);
  const behind = [];

  for (const row of owned) {
    const [{ max_id }] = await sql.unsafe(
      `SELECT COALESCE(max(${q(row.col)}), 0)::bigint AS max_id FROM public.${q(row.tbl)}`
    );
    const [{ last_value }] = await sql.unsafe(
      `SELECT last_value::bigint AS last_value FROM public.${q(row.seq)}`
    );
    const drift = BigInt(max_id) - BigInt(last_value);
    if (drift > 0n) {
      behind.push({ ...row, max_id, last_value, drift: drift.toString() });
    }
  }

  console.log(`Scanned ${owned.length} public sequences.`);

  if (behind.length === 0) {
    console.log("VERDICT: no sequence is behind its table. Inserts are safe.");
  } else {
    console.log(`VERDICT: ${behind.length} sequence(s) BEHIND their table.`);
    console.log("The next app insert into each of these dies on duplicate key:");
    for (const b of behind) {
      console.log(
        `  ${b.tbl}.${b.col}  sequence at ${b.last_value}, table already at ${b.max_id}  (behind by ${b.drift})`
      );
    }
    console.log("");
    console.log("FIX: run the 'Repair sequence drift' workflow, or locally:");
    console.log("  MODE=apply CONFIRM=repair-sequences node scripts/repair-sequence-drift.mjs");
  }

  // The visible half of the same fault: New Project is not transactional, so a
  // failed clone leaves the project row behind with no checklist at all.
  const orphans = await sql`
    SELECT p.id, p.code, p.created_at
      FROM projects p
     WHERE NOT EXISTS (SELECT 1 FROM project_checklist pc WHERE pc.project_id = p.id)
       AND NOT EXISTS (SELECT 1 FROM project_checklist_sections s WHERE s.project_id = p.id)
       AND p.created_at >= now() - interval '30 days'
     ORDER BY p.created_at DESC`;

  console.log("");
  if (orphans.length === 0) {
    console.log("No project created in the last 30 days is missing its checklist.");
  } else {
    console.log(
      `${orphans.length} project(s) created in the last 30 days have NO checklist at all —`
    );
    console.log("each is most likely a failed New Project click. Review before deleting:");
    for (const o of orphans) {
      console.log(`  id ${o.id}  ${o.code}  created ${o.created_at.toISOString()}`);
    }
  }
} finally {
  await sql.end({ timeout: 5 });
}
